// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "I have a my apps linux container running at 192.168.100.125. could you remake the app using tanstack and have the state of it persist with a local sqlite database. also use React for the UI with components from: https://www.reactbits.dev/. after you are done could you deploy it onto the container."
// Changes: History tab – named and automatic snapshots stored in SQLite, with create/restore/delete.

import { useServerFn } from '@tanstack/react-start'
import { useCallback, useEffect, useState } from 'react'
import { createSnapshotFn, deleteSnapshotFn, listSnapshotsFn, restoreSnapshotFn } from '#/server/projects.functions'
import type { ProjectRecord, SnapshotSummary } from '#/server/projects.server'
import { useToast } from './Toasts'
import { Button, DangerButton, Help, Panel, PrimaryButton, TextInput } from './ui'
import { SplitLayout } from './SplitLayout'

export const formatTime = (iso: string) => new Date(iso).toLocaleString('sk-SK', { dateStyle: 'medium', timeStyle: 'short' })

export function HistoryTab({
  projectId,
  flush,
  onRestored,
}: {
  projectId: string
  flush: () => Promise<void>
  onRestored: (record: ProjectRecord) => void
}) {
  const toast = useToast()
  const list = useServerFn(listSnapshotsFn)
  const create = useServerFn(createSnapshotFn)
  const restore = useServerFn(restoreSnapshotFn)
  const remove = useServerFn(deleteSnapshotFn)
  const [snapshots, setSnapshots] = useState<SnapshotSummary[] | null>(null)
  const [label, setLabel] = useState('')
  const [busy, setBusy] = useState(false)

  const reload = useCallback(async () => setSnapshots(await list({ data: { id: projectId } })), [list, projectId])
  useEffect(() => {
    void reload()
  }, [reload])

  const run = async (fn: () => Promise<void>, failTitle: string) => {
    setBusy(true)
    try {
      await fn()
    } catch (err) {
      toast({ title: failTitle, description: err instanceof Error ? err.message : String(err), tone: 'bad' })
    } finally {
      setBusy(false)
    }
  }

  const save = () =>
    run(async () => {
      await flush()
      await create({ data: { id: projectId, label: label.trim() || `Verzia ${new Date().toLocaleString('sk-SK')}` } })
      setLabel('')
      await reload()
      toast({ title: 'Verzia uložená', tone: 'ok' })
    }, 'Verziu sa nepodarilo uložiť')

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Make the two sections left and right resizable"
  // Changes: Resizable two-column layout.
  return (
    <SplitLayout>
      <Panel title="Uložiť verziu">
        <TextInput value={label} placeholder="napr. Pred zmenou výrazov" onChange={(e) => setLabel(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && void save()} aria-label="Popis verzie" />
        <div className="mt-3">
          <PrimaryButton onClick={() => void save()} disabled={busy}>
            Uložiť verziu
          </PrimaryButton>
        </div>
        <Help>
          Pri úpravách sa najviac raz za 20 minút uloží aj automatická záloha (posledných 30). Pred obnovením alebo importom sa
          aktuálny stav vždy odloží sem.
        </Help>
      </Panel>

      <Panel title="História">
        {snapshots === null ? (
          <div className="text-sm text-zinc-500">Načítavam…</div>
        ) : snapshots.length === 0 ? (
          <div className="text-sm text-zinc-500">Zatiaľ žiadne uložené verzie.</div>
        ) : (
          <ul className="divide-y divide-white/5">
            {snapshots.map((s) => (
              <li key={s.id} className="flex flex-wrap items-center gap-3 py-2.5">
                <div className="min-w-0 flex-1">
                  <div className="truncate text-sm text-zinc-200">{s.label}</div>
                  <div className="text-xs text-zinc-500">
                    {formatTime(s.createdAt)}
                    {s.auto && <span className="ml-2 rounded-full bg-white/5 px-2 py-0.5 text-[11px] text-zinc-400">auto</span>}
                  </div>
                </div>
                <Button
                  disabled={busy}
                  onClick={() => {
                    if (!confirm(`Obnoviť verziu „${s.label}“? Aktuálny stav sa najprv uloží do histórie.`)) return
                    void run(async () => {
                      await flush()
                      const record = await restore({ data: { snapshotId: s.id } })
                      if (!record) throw new Error('Verzia už neexistuje')
                      onRestored(record)
                      await reload()
                      toast({ title: 'Verzia obnovená', description: s.label, tone: 'ok' })
                    }, 'Obnovenie zlyhalo')
                  }}
                >
                  Obnoviť
                </Button>
                <DangerButton
                  disabled={busy}
                  onClick={() => {
                    if (!confirm(`Zmazať verziu „${s.label}“?`)) return
                    void run(async () => {
                      await remove({ data: { snapshotId: s.id } })
                      await reload()
                    }, 'Mazanie zlyhalo')
                  }}
                >
                  Zmazať
                </DangerButton>
              </li>
            ))}
          </ul>
        )}
      </Panel>
    </SplitLayout>
  )
}
